
using bai1;
using System.ComponentModel;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
namespace BookManager;

public class BookModel { public string BookId { get; set; } = ""; public string Title { get; set; } = ""; public string Author { get; set; } = ""; public int Quantity { get; set; } public decimal UnitPrice { get; set; } public string CoverPath { get; set; } = ""; public decimal InventoryValue => Quantity * UnitPrice; }
static class Program { [STAThread] static void Main() { ApplicationConfiguration.Initialize(); Application.Run(new MainForm()); } }
public class MainForm : Form
{
    BindingList<BookModel> books = new(); BindingSource bs = new(); TextBox id = new(), title = new(), author = new(), qty = new(), price = new(), cover = new(); PictureBox pic = new(); DataGridView grid = new(); ToolStripStatusLabel count = new(), value = new(), time = new(); string coverPath = "";
    public MainForm() { Text = "Book Manager"; Size = new(1200, 750); StartPosition = FormStartPosition.CenterScreen; Build(); bs.DataSource = books; grid.DataSource = bs; books.ListChanged += (_, __) => Status(); books.Add(new() { BookId = "S001", Title = "Lập trình C#", Author = "Nguyễn Văn A", Quantity = 5, UnitPrice = 120000 }); Status(); }
    void Build()
    {
        var menu = new MenuStrip(); var f = new ToolStripMenuItem("File"); f.DropDownItems.Add("Mở file CSV", null, (_, __) => Import()); f.DropDownItems.Add("Lưu file CSV", null, (_, __) => Export()); f.DropDownItems.Add("Thoát", null, (_, __) => Close()); var e = new ToolStripMenuItem("Edit"); e.DropDownItems.Add("Thêm", null, (_, __) => Add()); e.DropDownItems.Add("Xóa", null, (_, __) => Delete()); e.DropDownItems.Add("Tìm kiếm", null, (_, __) => Search()); menu.Items.Add(f); menu.Items.Add(e); MainMenuStrip = menu; Controls.Add(menu);
        var tool = new ToolStrip(); tool.Items.Add(new ToolStripButton("📂 Mở", null, (_, __) => Import())); tool.Items.Add(new ToolStripButton("💾 Lưu", null, (_, __) => Export())); tool.Items.Add(new ToolStripButton("➕ Thêm", null, (_, __) => Add())); Controls.Add(tool);
        var root = new TableLayoutPanel { Dock = DockStyle.Fill, Padding = new(8), RowCount = 3, ColumnCount = 1 }; root.RowStyles.Add(new(SizeType.Absolute, 230)); root.RowStyles.Add(new(SizeType.Percent, 100)); root.RowStyles.Add(new(SizeType.Absolute, 25)); Controls.Add(root); root.BringToFront();
        var top = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 2 }; top.ColumnStyles.Add(new(SizeType.Percent, 75)); top.ColumnStyles.Add(new(SizeType.Percent, 25)); var fields = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 3, RowCount = 3 }; for (int i = 0; i < 3; i++) fields.ColumnStyles.Add(new(SizeType.Percent, 33.3f)); for (int i = 0; i < 3; i++) fields.RowStyles.Add(new(SizeType.Percent, 33.3f)); Field(fields, "Mã sách", id, 0, 0); Field(fields, "Tên sách", title, 1, 0); Field(fields, "Tác giả", author, 2, 0); Field(fields, "Số lượng", qty, 0, 1); Field(fields, "Đơn giá", price, 1, 1); var imagePanel = new FlowLayoutPanel { Dock = DockStyle.Fill }; cover.ReadOnly = true; cover.Width = 140; imagePanel.Controls.Add(cover); var load = new Button { Text = "Tải ảnh bìa" }; load.Click += (_, __) => ChooseImage(); imagePanel.Controls.Add(load); fields.Controls.Add(imagePanel, 2, 1); var buttons = new FlowLayoutPanel { Dock = DockStyle.Fill }; buttons.Controls.Add(Btn("Thêm", (_, __) => Add())); buttons.Controls.Add(Btn("Sửa", (_, __) => Edit())); buttons.Controls.Add(Btn("Xóa", (_, __) => Delete())); fields.Controls.Add(buttons, 0, 2); fields.SetColumnSpan(buttons, 3); top.Controls.Add(fields, 0, 0); pic.Dock = DockStyle.Fill; pic.SizeMode = PictureBoxSizeMode.Zoom; pic.BorderStyle = BorderStyle.FixedSingle; top.Controls.Add(pic, 1, 0); root.Controls.Add(top, 0, 0);
        grid.Dock = DockStyle.Fill; grid.AutoGenerateColumns = false; grid.ReadOnly = true; grid.AllowUserToAddRows = false; grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect; grid.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill; Col("Mã", "BookId"); Col("Tên sách", "Title"); Col("Tác giả", "Author"); Col("SL", "Quantity"); Col("Đơn giá", "UnitPrice", "N0"); Col("Giá trị kho", "InventoryValue", "N0"); Col("Ảnh", "CoverPath"); grid.SelectionChanged += (_, __) => LoadRow(); root.Controls.Add(grid, 0, 1); var strip = new StatusStrip(); strip.Items.Add(count); strip.Items.Add(new ToolStripStatusLabel(" | ")); strip.Items.Add(value); strip.Items.Add(new ToolStripStatusLabel { Spring = true }); strip.Items.Add(time); root.Controls.Add(strip, 0, 2);
    }
    void Field(TableLayoutPanel p, string t, Control c, int x, int y) { var a = new TableLayoutPanel { Dock = DockStyle.Fill, RowCount = 2, ColumnCount = 1, Padding = new(3) }; a.RowStyles.Add(new(SizeType.Absolute, 22)); a.RowStyles.Add(new(SizeType.Percent, 100)); a.Controls.Add(new Label { Text = t, Dock = DockStyle.Fill }, 0, 0); c.Dock = DockStyle.Fill; a.Controls.Add(c, 0, 1); p.Controls.Add(a, x, y); }
    Button Btn(string t, EventHandler e) { var b = new Button { Text = t, Width = 80 }; b.Click += e; return b; }
    void Col(string t, string p, string fmt = null) { var c = new DataGridViewTextBoxColumn { HeaderText = t, DataPropertyName = p }; if (fmt != null) c.DefaultCellStyle.Format = fmt; grid.Columns.Add(c); }
    BookModel Selected() => grid.CurrentRow?.DataBoundItem as BookModel; BookModel Read() => new() { BookId = id.Text.Trim(), Title = title.Text.Trim(), Author = author.Text.Trim(), Quantity = int.Parse(qty.Text), UnitPrice = decimal.Parse(price.Text), CoverPath = coverPath };
    bool Valid() { if (string.IsNullOrWhiteSpace(id.Text) || string.IsNullOrWhiteSpace(title.Text) || !int.TryParse(qty.Text, out int q) || q < 0 || !decimal.TryParse(price.Text, out decimal p) || p < 0) { MessageBox.Show("Nhập mã/tên sách, số lượng nguyên không âm và đơn giá hợp lệ."); return false; } if (books.Any(x => x.BookId == id.Text.Trim() && !ReferenceEquals(x, Selected()))) { MessageBox.Show("Mã sách trùng."); return false; } return true; }
    void Add() { if (Valid()) { books.Add(Read()); Clear(); } }
    void Edit() { var x = Selected(); if (x == null || !Valid()) { if (x == null) MessageBox.Show("Chọn sách."); return; } var v = Read(); x.BookId = v.BookId; x.Title = v.Title; x.Author = v.Author; x.Quantity = v.Quantity; x.UnitPrice = v.UnitPrice; x.CoverPath = v.CoverPath; bs.ResetBindings(false); Status(); }
    void Delete() { var x = Selected(); if (x != null && MessageBox.Show("Xóa sách?", "Xác nhận", MessageBoxButtons.YesNo, MessageBoxIcon.Warning) == DialogResult.Yes) { books.Remove(x); Clear(); } }
    void Clear() { id.Clear(); title.Clear(); author.Clear(); qty.Clear(); price.Clear(); cover.Clear(); coverPath = ""; ShowImage(""); }
    void LoadRow() { var x = Selected(); if (x == null) return; id.Text = x.BookId; title.Text = x.Title; author.Text = x.Author; qty.Text = x.Quantity.ToString(); price.Text = x.UnitPrice.ToString("0.##"); coverPath = x.CoverPath; cover.Text = Path.GetFileName(coverPath); ShowImage(coverPath); }
    void ChooseImage() { using var d = new OpenFileDialog { Filter = "Ảnh (*.png;*.jpg;*.jpeg)|*.png;*.jpg;*.jpeg" }; if (d.ShowDialog() == DialogResult.OK) { coverPath = d.FileName; cover.Text = Path.GetFileName(coverPath); ShowImage(coverPath); } }
    void ShowImage(string path) { try { pic.Image?.Dispose(); pic.Image = null; if (File.Exists(path)) { using var fs = File.OpenRead(path); using var im = Image.FromStream(fs); pic.Image = new Bitmap(im); } } catch { pic.Image = null; } }
    void Status() { count.Text = $"Tổng số đầu sách: {books.Count}"; value.Text = $"Tổng giá trị kho: {books.Sum(x => x.InventoryValue):N0} VNĐ"; time.Text = DateTime.Now.ToString("HH:mm:ss"); }
    void Export() { using var d = new SaveFileDialog { Filter = "CSV (*.csv)|*.csv", FileName = "Books.csv" }; if (d.ShowDialog() != DialogResult.OK) return; var sb = new StringBuilder("BookId,Title,Author,Quantity,UnitPrice,CoverPath\r\n"); foreach (var b in books) sb.AppendLine(string.Join(",", new[] { b.BookId, b.Title, b.Author, b.Quantity.ToString(), b.UnitPrice.ToString(CultureInfo.InvariantCulture), b.CoverPath }.Select(Csv))); File.WriteAllText(d.FileName, "\uFEFF" + sb, Encoding.UTF8); MessageBox.Show("Đã lưu CSV."); }
    void Import() { using var d = new OpenFileDialog { Filter = "CSV (*.csv)|*.csv" }; if (d.ShowDialog() != DialogResult.OK) return; try { var rows = File.ReadAllLines(d.FileName, Encoding.UTF8); books.Clear(); foreach (var line in rows.Skip(1)) { var a = Parse(line); if (a.Length >= 6 && int.TryParse(a[3], out int q) && decimal.TryParse(a[4], NumberStyles.Any, CultureInfo.InvariantCulture, out decimal p)) books.Add(new() { BookId = a[0], Title = a[1], Author = a[2], Quantity = q, UnitPrice = p, CoverPath = a[5] }); } MessageBox.Show($"Đã nhập {books.Count} sách."); } catch (Exception ex) { MessageBox.Show(ex.Message); } }
    void Search() { string s = Microsoft.VisualBasic.Interaction.InputBox("Nhập mã hoặc tên sách:", "Tìm kiếm"); var x = books.FirstOrDefault(b => b.BookId.Contains(s, StringComparison.OrdinalIgnoreCase) || b.Title.Contains(s, StringComparison.OrdinalIgnoreCase)); if (x == null) { MessageBox.Show("Không tìm thấy."); return; } foreach (DataGridViewRow r in grid.Rows) if (ReferenceEquals(r.DataBoundItem, x)) { r.Selected = true; grid.CurrentCell = r.Cells[0]; break; } }
    string Csv(string s) => "\"" + (s ?? "").Replace("\"", "\"\"") + "\""; string[] Parse(string line) { var l = new System.Collections.Generic.List<string>(); var b = new StringBuilder(); bool q = false; for (int i = 0; i < line.Length; i++) { char c = line[i]; if (c == '"') { if (q && i + 1 < line.Length && line[i + 1] == '"') { b.Append('"'); i++; } else q = !q; } else if (c == ',' && !q) { l.Add(b.ToString()); b.Clear(); } else b.Append(c); } l.Add(b.ToString()); return l.ToArray(); }
    protected override void OnFormClosed(FormClosedEventArgs e) { pic.Image?.Dispose(); base.OnFormClosed(e); }
}
